import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import API from '../api/axios';
import { ShieldAlert, CheckCircle, Smartphone, Lock } from 'lucide-react';

export default function Login() {
  const navigate = useNavigate();
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  // JWT Token Payload Decoder
  const parseJwt = (token) => {
    try {
      const base64Url = token.split('.')[1];
      const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
      const jsonPayload = decodeURIComponent(
        atob(base64)
          .split('')
          .map((c) => '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2))
          .join('')
      );
      return JSON.parse(jsonPayload);
    } catch (e) {
      return null;
    }
  };

  // Google One Tap Callback Handler
  const handleGoogleCallback = async (response) => {
    setLoading(true);
    setError('');

    const decoded = parseJwt(response.credential);
    if (!decoded || !decoded.email) {
      setError('Google theke account information paowa jai ni!');
      setLoading(false);
      return;
    }

    try {
      const res = await API.post('/auth/google-login', {
        email: decoded.email,
        name: decoded.name || decoded.email.split('@')[0]
      });

      if (res.data.success && res.data.token) {
        localStorage.setItem('admin_token', res.data.token);
        localStorage.setItem('admin_user', JSON.stringify(res.data.user));
        navigate('/dashboard');
      }
    } catch (err) {
      setError(err.response?.data?.error || 'Ei Gmail-ti admin hishebe onumodito na!');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (localStorage.getItem('admin_token')) {
      navigate('/dashboard');
      return;
    }

    // Google Identity Service Initialize
    const initializeGoogle = () => {
      if (window.google) {
        window.google.accounts.id.initialize({
          client_id: "892348234723-dummyclientid.apps.googleusercontent.com",
          callback: handleGoogleCallback,
          auto_select: true
        });

        // Button Render
        const btnContainer = document.getElementById('googleSignInBtn');
        if (btnContainer) {
          window.google.accounts.id.renderButton(btnContainer, {
            theme: 'filled_blue',
            size: 'large',
            shape: 'pill',
            width: 300
          });
        }

        // Phone ba PC te logged-in thaka Gmail Prompt Show kora
        window.google.accounts.id.prompt();
      }
    };

    const timer = setTimeout(initializeGoogle, 400);
    return () => clearTimeout(timer);
  }, [navigate]);

  // Direct Authorized Login for tanvir.it009@gmail.com
  const handleTanvirLogin = async () => {
    setLoading(true);
    setError('');
    try {
      const res = await API.post('/auth/google-login', {
        email: 'tanvir.it009@gmail.com',
        name: 'Tanvir (Super Admin)'
      });

      if (res.data.token) {
        localStorage.setItem('admin_token', res.data.token);
        localStorage.setItem('admin_user', JSON.stringify(res.data.user));
        navigate('/dashboard');
      }
    } catch (err) {
      setError(err.response?.data?.error || 'Login fail hoyeche!');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4 font-sans">
      <div className="bg-white rounded-3xl p-8 max-w-sm w-full shadow-2xl space-y-6 text-center">
        <div>
          <div className="w-16 h-16 bg-emerald-100 text-emerald-800 rounded-2xl flex items-center justify-center mx-auto mb-3 font-black text-2xl shadow-inner">
            CF
          </div>
          <h2 className="text-2xl font-black text-gray-900">CityFood Control</h2>
          <p className="text-xs text-gray-500 font-semibold mt-1">Admin Panel Security</p>
        </div>

        {error && (
          <div className="p-3 bg-red-50 border border-red-200 text-red-700 text-xs rounded-xl flex items-center gap-2 font-bold text-left">
            <ShieldAlert className="w-4 h-4 flex-shrink-0 text-red-600" />
            <span>{error}</span>
          </div>
        )}

        {/* Browser / Phone Gmail Sign-In Box */}
        <div className="flex flex-col items-center justify-center space-y-3 py-1">
          <div id="googleSignInBtn" className="flex justify-center"></div>
          <p className="text-[11px] text-gray-400">
            Phone ba PC-te login thaka Gmail auto-detect hobe.
          </p>
        </div>

        <div className="relative flex py-1 items-center">
          <div className="flex-grow border-t border-gray-200"></div>
          <span className="flex-shrink mx-2 text-gray-300 text-[10px] font-black uppercase">Super Admin Access</span>
          <div className="flex-grow border-t border-gray-200"></div>
        </div>

        {/* 1-Click Super Admin Login Button */}
        <button
          onClick={handleTanvirLogin}
          disabled={loading}
          className="w-full py-3.5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-2xl font-bold text-xs shadow-lg shadow-emerald-600/30 transition-all flex items-center justify-center gap-2 cursor-pointer active:scale-95"
        >
          <CheckCircle className="w-4 h-4" />
          {loading ? 'Checking...' : 'Sign in as tanvir.it009@gmail.com'}
        </button>

        <div className="bg-gray-50 p-3 rounded-2xl border border-gray-100 text-[10px] text-gray-500 font-medium leading-relaxed">
          🔒 Shudhumatro <strong>tanvir.it009@gmail.com</strong> ebong panel theke add kora onumodito sub-admin accounts dukhte parbe.
        </div>
      </div>
    </div>
  );
}
